import{c as s}from"./chunks/caution.DjUmlKPe.js";import{$ as n,Q as i,j as p,m as o,h as c,ay as t,n as a,o as r,S as u,g as d}from"./chunks/framework.Cr5Oofs_.js";import"./chunks/alert.CQjRNMKX.js";/* empty css                                                                                  */const h="/pyclickmouse/imgs/zh-CN/mergeSteps.png",q=JSON.parse('{"title":"参与协作","description":"介绍如何参加协作","frontmatter":{"title":"参与协作","description":"介绍如何参加协作","layout":"doc"},"headers":[],"relativePath":"zh-CN/develop/contributing/github.md","filePath":"zh-CN/develop/contributing/github.md"}'),m={name:"zh-CN/develop/contributing/github.md"},A=Object.assign(m,{setup(b){return(g,e)=>{const l=n("Mermaid");return i(),p("div",null,[e[2]||(e[2]=o(`<h1 id="参与协作" tabindex="-1">参与协作 <a class="header-anchor" href="#参与协作" aria-label="Permalink to &quot;参与协作&quot;">​</a></h1><h2 id="commit-message" tabindex="-1">commit message <a class="header-anchor" href="#commit-message" aria-label="Permalink to &quot;commit message&quot;">​</a></h2><p>需要遵循以下格式:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>更新类型(更新模块):(可选)(版本号) (更新概括):</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- [(可选)子更新类型]更新内容1</span></span>
<span class="line"><span>- [(可选)子更新类型]更新内容2</span></span>
<span class="line"><span>- ...</span></span></code></pre></div><p>更新类型有这些内容:</p><table tabindex="0"><thead><tr><th>类型</th><th>说明</th></tr></thead><tbody><tr><td>✅feat</td><td>新功能</td></tr><tr><td>🔧modify</td><td>修改功能</td></tr><tr><td>🐛fix</td><td>修bug</td></tr><tr><td>⚒️refactor</td><td>重构</td></tr><tr><td>📃docs</td><td>改文档，比如README</td></tr><tr><td>❇️style</td><td>改代码风格，不影响功能</td></tr><tr><td>🔎test</td><td>加测试、改测试</td></tr><tr><td>📆chore</td><td>杂项，比如改.gitignore</td></tr><tr><td>⏫perf</td><td>性能优化</td></tr><tr><td>🛒ci</td><td>CI/CD相关改动</td></tr><tr><td>🚅build</td><td>改构建系统或依赖</td></tr><tr><td>◀️revert</td><td>回滚</td></tr><tr><td>🔡dependency</td><td>依赖更新</td></tr><tr><td>❌remove</td><td>删除弃用的组件</td></tr><tr><td>↪️move</td><td>移动了组件</td></tr><tr><td>❓unknown</td><td>未知类型</td></tr><tr><td>自定义</td><td>尽量以一个直观的英文单词描述，最好配上emoji</td></tr></tbody></table><p>内容较多时需要对更新内容添加更新类型提示</p><h2 id="分支" tabindex="-1">分支 <a class="header-anchor" href="#分支" aria-label="Permalink to &quot;分支&quot;">​</a></h2><p>请按此图所示的分支结构来更新： <img src="`+h+'" alt="合并步骤"></p><p>创建的分支需要以<code>feature/</code>开头，以表示功能分支，或创建一个fork，并在fork的分支开发。</p><p>发布pr时要选择<strong>合并到<code>develop</code>分支</strong>。</p><h2 id="版本号" tabindex="-1">版本号 <a class="header-anchor" href="#版本号" aria-label="Permalink to &quot;版本号&quot;">​</a></h2><p>clickmouse版本格式为：<code>A.B.C.D[(alpha | beta |.dev | rc) E]</code></p><h2 id="正式版本" tabindex="-1">正式版本 <a class="header-anchor" href="#正式版本" aria-label="Permalink to &quot;正式版本&quot;">​</a></h2><p>正式版不带.dev、alpha、beta或rc后缀。</p><p>A位代表有重大更新，有代码级的变动。如1.0升级到2.0就重构了代码。</p><p>B位代表有普通更新，通常是更新一些大功能。</p><p>C位代表有修复更新，通常会更新一些小功能和一些bug。</p><p>D位代表版本代号，通常每A, B, C位有变动时候+1。也有可能A, B, C位没有变动，D位+1，这代表紧急更新，通常是修复几个重大影响的bug。</p><h2 id="测试版本" tabindex="-1">测试版本 <a class="header-anchor" href="#测试版本" aria-label="Permalink to &quot;测试版本&quot;">​</a></h2><p>测试版本带.dev、alpha、beta或rc后缀。</p><p>通常前面的<code>A.B.C.D</code>在一个测试周期内不变，代表下一个版本。</p><p><code>.dev</code>代表早期开发更新，功能不稳定，bug很多，位于版本项目初期。这阶段新增的功能将会被放到实验室中，并默认关闭。</p><p><code>alpha</code>代表晚期开发更新，功能不完善，bug较多，位于版本项目早期。这阶段新增的功能将会被放到实验室中，并默认关闭。</p><p><code>beta</code>代表发布测试更新，功能完善，bug较少，不会再新增功能，位于版本项目中期，并且会逐步合并实验室中的feature。</p><p><code>rc</code>代表预备发布版本，功能完善，bug较少，会修复一些重要安全问题或bug，最接近正式版，即将发布正式版，位于版本项目末期。</p><h2 id="issue" tabindex="-1">issue <a class="header-anchor" href="#issue" aria-label="Permalink to &quot;issue&quot;">​</a></h2><ul><li>标题格式：<code>[类型] 标题</code>等，可以随便写，但要准确描述更新内容。</li><li>内容应准确写出你的需求，并选择性给出解决方案，上传截图，添加附加信息（如clickmouse版本号）</li><li>类型为<code>bug</code>、<code>enhancement</code>、<code>question</code>等。</li><li>我们给了一些模板，可直接使用。</li><li>使用<code>labels</code>来标记issue的类型，比如<code>bug</code>、<code>enhancement</code>、<code>question</code>等。</li><li>设置issue的<code>milestone</code>为你想应用的issue版本。</li><li>安全问题请见<a href="./SECURITY.html">安全说明文档</a>。</li></ul><h2 id="pr" tabindex="-1">pr <a class="header-anchor" href="#pr" aria-label="Permalink to &quot;pr&quot;">​</a></h2><ul><li>标题格式：<code>[类型] 标题</code></li><li>使用<code>labels</code>来标记pr的类型，比如<code>bug</code>、<code>enhancement</code>、<code>question</code>等。</li><li>关联issue，这样我们就可以知道这个pr解决了哪个issue。</li><li>需要准确写出更新内容，关联到版本号的milestone。</li><li>可选添加实现思路</li></ul><h3 id="规范" tabindex="-1">规范 <a class="header-anchor" href="#规范" aria-label="Permalink to &quot;规范&quot;">​</a></h3><p>我们pr合并的顺序为：</p>',32)),(i(),c(u,null,{default:t(()=>[r(l,{id:"mermaid-300",class:"mermaid",graph:"graph%20LR%0AA(%E5%85%B6%E4%BB%96%E7%94%A8%E6%88%B7%E7%9A%84%E5%8A%9F%E8%83%BD%E5%BC%80%E5%8F%91%E5%88%86%E6%94%AF)%20--%3E%20B(develop%E5%88%86%E6%94%AF)%0AB%20--%3E%20C(main%E5%88%86%E6%94%AF)%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[a(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=d("p",null,"pr无特定格式，但是必须清晰描述更新内容，关联到版本号的milestone；标题要简略描述更新内容，若修复或添加了issue里的建议，把该issue编号写进该行为，若出现多个重复issue，则只用写一个，并简单描述此bug。",-1)),e[4]||(e[4]=d("h3",{id:"快车pr",tabindex:"-1"},[a("快车pr "),d("a",{class:"header-anchor",href:"#快车pr","aria-label":'Permalink to "快车pr"'},"​")],-1)),r(s,{title:"警告"},{default:t(()=>[...e[1]||(e[1]=[a(" 快车pr请谨慎使用 ",-1)])]),_:1}),e[5]||(e[5]=o('<ul><li>快车pr的意思是跳过部分正常的pr合并分支步骤，以更快的合并到目标分支的功能。</li><li>标题格式：<code>[✈️快车] 标题</code></li><li>使用快车必须在pr描述中说明使用的原因</li></ul><p>如果有人快车合并，但没写快车合并的原因，则拒绝合并该人的分支。</p><p>快车pr有高优先级，会优先进行处理。</p><h2 id="milestone" tabindex="-1">milestone <a class="header-anchor" href="#milestone" aria-label="Permalink to &quot;milestone&quot;">​</a></h2><ul><li>我们给每个版本都设置了一个milestone，用来管理该版本的issue和pr。</li><li>需要每个issue或pr都关联到一个milestone，这样我们才能知道该issue或pr是否在下个版本中添加。</li><li>milestone格式为:<code>dev_版本号</code></li></ul>',5))])}}});export{q as __pageData,A as default};
